export function illustration(name, className='') {
  return '<svg class="'+className+'" viewBox="0 0 100 80" aria-hidden="true">'+art[name]+'</svg>';
}

const buttonFrames = {
  press:[{}, {transform:'scale(1.025)',offset:.22}, {}],
  shake:[{}, {transform:'translateX(0)',offset:.24}, {transform:'translateX(-4px)',offset:.35},{transform:'translateX(4px)',offset:.43},{transform:'translateX(-2px)',offset:.52},{}],
  shy:[{}, {transform:'scale(.96)',offset:.24}, {transform:'scale(1)',offset:.6}, {}],
  glow:[{}, {boxShadow:'0 0 0 8px #edabc34d',offset:.27}, {}],
};
export const reducedMotion = () => matchMedia('(prefers-reduced-motion: reduce)').matches;

export function makePlayer() {
  let timer;
  let animations = [];
  let active;
  function stopEffect() {
    clearTimeout(timer);
    animations.forEach(animation => animation.cancel());
    animations = [];
    if (active) {
      active.stage.replaceChildren();
      active.stage.style.backgroundColor = '';
      active.stage.removeAttribute('data-effect');
      active.caption.textContent = '';
      active = undefined;
    }
  }
  function playEffect(id, target, stage, caption) {
    stopEffect();
    const scene = effects[id];
    if (!scene) return;
    const [message, objects, accent, tint, endTint] = scene;
    active = {stage,caption};
    const reduced = reducedMotion();
    const duration = config.effectMs + (id.startsWith('Q15') ? 480 : 0);
    caption.textContent = message;
    stage.dataset.effect = id;
    try {
      stage.style.backgroundColor = endTint || tint || '';
      stage.innerHTML = '<svg viewBox="0 0 320 100" aria-hidden="true">'+objects.map(([name,size,frames])=>{
        const [,x,y,scale,angle] = frames.reduce((best, frame) => (frame[5] ?? 1) >= (best[5] ?? 1) ? frame : best);
        return '<g style="transform:translate('+x+'px,'+y+'px) rotate('+angle+'deg) scale('+scale+')"><svg x="'+(-size/2)+'" y="'+(-size*.4)+'" width="'+size+'" height="'+size*.8+'" viewBox="0 0 100 80">'+art[name]+'</svg></g>';
      }).join('')+'</svg>';
      if (!reduced && stage.animate) {
        if (endTint) animations.push(stage.animate([{backgroundColor:tint},{backgroundColor:endTint}],duration));
        objects.forEach(([, , frames],i)=>{
          const keyframes = frames.map(([offset,x,y,scale,angle,opacity])=>({
            offset, transform:'translate('+x+'px,'+y+'px) rotate('+angle+'deg) scale('+scale+')', opacity,
          }));
          animations.push(stage.firstElementChild.children[i].animate(keyframes,{duration,easing:'ease-in-out',fill:'both'}));
        });
        if (accent && target?.animate) animations.push(target.animate(buttonFrames[accent],duration*.74));
        animations.push(stage.firstElementChild.animate([{opacity:1},{opacity:1,offset:.86},{opacity:0}],{duration,fill:'both'}));
      }
    } catch {
      animations.forEach(animation => animation.cancel());
      animations = [];
      stage.replaceChildren();
    }
    timer = setTimeout(stopEffect, reduced ? 1650 : duration + 50);
  }
  return {playEffect,stopEffect};
}
